e(C,183,None,'Plasma Attacks','rule',O,'Plasma Weapon Attacks should be +2 Multiplier versus shields, not "Double Damage" as described here. This brings it in line with the description for Counter: Shields on P212.',
  [(None,'Effect against Force Fields','Double Damage','+2 Weapon Multiplier')])
e(C,183,None,'Terran psionic Force Fields','rule',O,"Terran Sphere psionics using force fields circumvent the restriction on Psionic effects by having a gap in their force field's protection. This means that their force fields may be bypassed by aimed or area attacks that happen while they are using their powers. Normally this vulnerability only lasts for the Psionics turn, leaving them vulnerable to sustained attacks, but ongoing effects require the gap to remain open and exploitable.")
e(C,185,None,'Armor reduction duration','rule',O,"Armor Reduction from Coordinated Fire or from attacks with Counter: Armor persists until the end of the round, allowing subsequent players to take advantage of the target's weakened state.")
e(C,191,None,'Battle Strain: missile salvos','rule',O,'Battle strain can be spent on a 1 to 1 basis to increase the number of missiles in a salvo. This can not be used in conjunction with the Coordinated fire effect.')
e(C,191,None,'Battle Strain: Tags and extra actions','rule',O,'Using Battle Strain to Activate Tags or Perform Extra Actions with a unit does not fall under the single Battle Strain expenditure per round rule. Additional extra actions after the first cost increasing multiples of 3 Battle Strain (6, 9, etc...) as per the extra actions for AP rule.')
e(C,191,None,'Attached characters: skill switch','rule',O,"A character attached to a unit may use Tags and their personal AP to skill switch from the unit's target number on to their corresponding skill.")
e(C,194,None,'Missile attacks vs margin of defense','rule',O,"Missile attacks reduce their targets' total margin of defense by the number of attacking missiles in the salvo not -1 per salvo launched at the target. This reduction is not restricted to their bonus margin of defense from anti missile fire.",
  [(None,'Margin of defense reduction','-1 per salvo','-1 per missile in the salvo')])
e(IC,210,None,'Attack: turrets','rule',O,'Omission of Turret rules from Attack attribute - Spending the base cost for an attack multiple times allows additional gunners to make attacks with the weapon, or the same gunner assuming he spends the action points. The Ships of the Line design exercise starting on page 219 provides an example of these rules in action.')
e(IC,210,None,'Attack: Melee','rule',O,'Melee attacks can never gain the Area attribute.')
e(IC,212,None,'Counter: Armor','rule',O,'Counter Armor no longer can bypass non-partial armor on an aimed attack. Instead on an unaimed attack it will reduce armor by 1. Aimed attacks will grant an additional 1 armor reduction for the attack, bringing the aimed attack to -2 armor. However, the armor reduction contributed to other attacks remains at -1 armor.',
  [(None,'Armor reduction','-2, or ignore armor on an aimed attack','-1 unaimed; -2 aimed; -1 carries to other attacks')])
